BEGIN;
SET LOCAL ROLE service_role;
DO $$
DECLARE actor uuid:=gen_random_uuid();other_actor uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();link uuid;click uuid;sub jsonb;sub2 jsonb;job jsonb;prepared jsonb;receipt jsonb;page jsonb;old_version uuid;old_body text;key uuid;limited uuid;n integer;
secret text:='whsec_'||repeat('A',43)||'=';secret2 text:='whsec_'||repeat('B',43)||'=';
BEGIN
 INSERT INTO auth.users(id) VALUES(actor),(other_actor),(outsider);INSERT INTO public.user_roles VALUES(actor,'admin'),(other_actor,'admin');
 sub:=public.redirect_webhook_resource('create',actor,NULL,NULL,jsonb_build_object('name','Receiver','url','https://receiver.example.org/events','eventTypes',ARRAY['link.created','link.updated','link.deleted','link.clicked','lead.created','sale.created']),secret);
 IF sub->>'secret'<>secret OR sub->>'version' IS NULL THEN RAISE EXCEPTION 'Creation lost one-time secret/version';END IF;
 IF public.redirect_webhook_resource('get',actor,NULL,(sub->>'id')::uuid)?'secret' THEN RAISE EXCEPTION 'Secret leaked in metadata';END IF;
 BEGIN PERFORM public.redirect_webhook_resource('list',outsider,NULL);RAISE EXCEPTION 'Non-owner accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 INSERT INTO public.redirect_api_tokens(name,token_hash,prefix,scopes,created_by,expires_at) VALUES('Owner webhook',repeat('f',64),'fixture',ARRAY['workspace:read','workspace:write','events:read'],actor,now()+interval '1 day') RETURNING id INTO key;
 IF public.redirect_webhook_resource('get',NULL,key,(sub->>'id')::uuid)->>'id'<>sub->>'id' THEN RAISE EXCEPTION 'Owner key denied';END IF;
 INSERT INTO public.redirects(type,slug,target) VALUES('SHORT','webhook-private','https://example.org/private?password=hidden') RETURNING id INTO link;
 INSERT INTO public.redirect_api_tokens(name,token_hash,prefix,scopes,redirect_ids,created_by,expires_at) VALUES('Limited webhook',repeat('e',64),'fixture',ARRAY['workspace:read','workspace:write','events:read'],ARRAY[link],actor,now()+interval '1 day') RETURNING id INTO limited;
 BEGIN PERFORM public.redirect_webhook_resource('list',NULL,limited);RAISE EXCEPTION 'ID-limited key accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 IF (SELECT count(*) FROM public.redirect_webhook_events WHERE redirect_id=link AND type='link.created')<>1 THEN RAISE EXCEPTION 'Create event missing';END IF;
 UPDATE public.redirects SET target='https://example.org/other-secret',notes='private note' WHERE id=link;
 UPDATE public.redirects SET target='https://example.org/final-secret' WHERE id=link;
 IF (SELECT count(*) FROM public.redirect_webhook_events WHERE redirect_id=link AND type='link.updated')<>1 THEN RAISE EXCEPTION 'Lifecycle not coalesced';END IF;
 click:=public.record_redirect_visit(link,'/go/webhook-private','https://private.example.org/ref?secret=hidden','127.0.0.1','Fixture','CH',NULL,302,NULL,'https://example.org/private?password=hidden');
 IF (SELECT count(*) FROM public.redirect_webhook_events WHERE redirect_id=link AND type='link.updated')<>1 THEN RAISE EXCEPTION 'Click counter emitted lifecycle event';END IF;
 PERFORM public.record_redirect_conversion(jsonb_build_object('kind','lead','clickId',click,'customerExternalId','sensitive-customer','eventId','webhook-lead','eventName','Sign up'));
 IF EXISTS(SELECT FROM public.redirect_webhook_deliveries WHERE webhook_id=(sub->>'id')::uuid AND (body LIKE '%hidden%' OR body LIKE '%sensitive-customer%' OR body LIKE '%private note%' OR body LIKE '%127.0.0.1%')) THEN RAISE EXCEPTION 'Private payload data leaked';END IF;
 job:=public.claim_redirect_webhook_deliveries(4)->0;
 IF job IS NULL OR job?'body' OR job?'secret' THEN RAISE EXCEPTION 'Claim missing or leaked secrets';END IF;
 IF jsonb_array_length(public.claim_redirect_webhook_deliveries(4))<>0 THEN RAISE EXCEPTION 'Endpoint acquired overlapping lease';END IF;
 prepared:=public.prepare_redirect_webhook_delivery((job->>'id')::uuid,(job->>'lease')::uuid);old_body:=prepared->>'body';
 receipt:=public.finish_redirect_webhook_delivery((job->>'id')::uuid,(job->>'lease')::uuid,503,'http_error','Temporarily unavailable',20,120);
 IF receipt->>'state'<>'retry' OR (receipt->>'attempts')::integer<>1 OR (receipt->>'nextAttemptAt')::timestamptz<clock_timestamp()+interval '110 seconds' THEN RAISE EXCEPTION 'Retry/backoff receipt invalid';END IF;
 BEGIN PERFORM public.finish_redirect_webhook_delivery((job->>'id')::uuid,(job->>'lease')::uuid,200,NULL,'',1);RAISE EXCEPTION 'Old lease acknowledged twice';EXCEPTION WHEN no_data_found THEN NULL;END;
 UPDATE public.redirect_webhook_deliveries SET next_attempt_at=clock_timestamp()-interval '1 second' WHERE id=(job->>'id')::uuid;
 job:=public.claim_redirect_webhook_deliveries(4)->0;
 IF public.prepare_redirect_webhook_delivery((job->>'id')::uuid,(job->>'lease')::uuid)->>'body'<>old_body THEN RAISE EXCEPTION 'Retry body changed';END IF;
 sub:=public.redirect_webhook_resource('rotate',other_actor,NULL,(sub->>'id')::uuid,jsonb_build_object('version',sub->>'version'),secret2);
 prepared:=public.prepare_redirect_webhook_delivery((job->>'id')::uuid,(job->>'lease')::uuid);
 IF prepared->>'secret'<>secret2 OR prepared->>'previousSecret'<>secret THEN RAISE EXCEPTION 'Rotation overlap lost';END IF;
 receipt:=public.finish_redirect_webhook_delivery((job->>'id')::uuid,(job->>'lease')::uuid,204,NULL,'',3);
 IF receipt->>'state'<>'delivered' THEN RAISE EXCEPTION 'Success receipt invalid';END IF;
 page:=public.redirect_webhook_delivery_resource('get',actor,NULL,(sub->>'id')::uuid,(job->>'id')::uuid);
 IF page->>'body'<>old_body OR jsonb_array_length(page->'recentAttempts')<>2 THEN RAISE EXCEPTION 'History lost attempts/body';END IF;
 receipt:=public.redirect_webhook_delivery_resource('replay',actor,NULL,(sub->>'id')::uuid,(job->>'id')::uuid,jsonb_build_object('version',receipt->>'version'));
 IF receipt->>'state'<>'queued' OR (receipt->>'replays')::integer<>1 THEN RAISE EXCEPTION 'Replay not queued';END IF;
 BEGIN PERFORM public.redirect_webhook_delivery_resource('replay',actor,NULL,(sub->>'id')::uuid,(job->>'id')::uuid,jsonb_build_object('version',page->>'version'));RAISE EXCEPTION 'Stale replay accepted';EXCEPTION WHEN unique_violation THEN NULL;END;
 job:=public.claim_redirect_webhook_deliveries(4)->0;
 old_version:=(sub->>'version')::uuid;
 sub:=public.redirect_webhook_resource('patch',actor,NULL,(sub->>'id')::uuid,jsonb_build_object('version',old_version,'enabled',false));
 IF EXISTS(SELECT FROM public.redirect_webhook_deliveries WHERE webhook_id=(sub->>'id')::uuid AND state IN('queued','retry')) THEN RAISE EXCEPTION 'Pause left queued work';END IF;
 BEGIN PERFORM public.prepare_redirect_webhook_delivery((job->>'id')::uuid,(job->>'lease')::uuid);RAISE EXCEPTION 'Paused lease prepared';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 receipt:=public.finish_redirect_webhook_delivery((job->>'id')::uuid,(job->>'lease')::uuid,NULL,'scope_changed','',0);
 IF receipt->>'state'<>'cancelled' THEN RAISE EXCEPTION 'Paused lease did not close its denial receipt';END IF;
 BEGIN PERFORM public.redirect_webhook_resource('patch',actor,NULL,(sub->>'id')::uuid,jsonb_build_object('version',old_version,'enabled',true));RAISE EXCEPTION 'Stale settings accepted';EXCEPTION WHEN unique_violation THEN NULL;END;
 receipt:=public.redirect_webhook_resource('test',actor,NULL,(sub->>'id')::uuid,jsonb_build_object('version',sub->>'version'));
 IF NOT (receipt->>'queued')::boolean THEN RAISE EXCEPTION 'Disabled endpoint cannot explicitly test';END IF;
 job:=public.claim_redirect_webhook_deliveries(4)->0;
 IF job IS NULL THEN RAISE EXCEPTION 'Test not claimed';END IF;
 DELETE FROM public.user_roles WHERE user_id=actor;
 BEGIN PERFORM public.prepare_redirect_webhook_delivery((job->>'id')::uuid,(job->>'lease')::uuid);RAISE EXCEPTION 'Former owner callback prepared';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM public.prune_redirect_webhooks(100);
 IF EXISTS(SELECT FROM public.redirect_webhook_deliveries WHERE webhook_id=(sub->>'id')::uuid AND state IN('queued','retry')) OR NOT EXISTS(SELECT FROM public.redirect_webhook_deliveries WHERE id=(job->>'id')::uuid AND state='leased') THEN RAISE EXCEPTION 'Lost owner cleanup lost queued cancellation or in-flight receipt';END IF;
 receipt:=public.finish_redirect_webhook_delivery((job->>'id')::uuid,(job->>'lease')::uuid,200,NULL,'accepted before role loss',1);
 IF receipt->>'state'<>'cancelled' OR receipt->>'httpStatus'<>'200' THEN RAISE EXCEPTION 'Lost-owner external receipt lost';END IF;
 sub2:=public.redirect_webhook_resource('create',other_actor,NULL,NULL,jsonb_build_object('name','Retry receiver','url','https://receiver.example.org/retry'),secret);
 receipt:=public.redirect_webhook_resource('test',other_actor,NULL,(sub2->>'id')::uuid,jsonb_build_object('version',sub2->>'version'));
 FOR n IN 1..8 LOOP
  job:=public.claim_redirect_webhook_deliveries(4)->0;
  receipt:=public.finish_redirect_webhook_delivery((job->>'id')::uuid,(job->>'lease')::uuid,503,'http_error','Unavailable',2);
  IF receipt->>'state'<>(CASE WHEN n=8 THEN 'failed' ELSE 'retry' END) THEN RAISE EXCEPTION 'Retry attempt % has wrong terminal state',n;END IF;
  UPDATE public.redirect_webhook_deliveries SET next_attempt_at=clock_timestamp()-interval '1 second' WHERE id=(job->>'id')::uuid;
 END LOOP;
 IF jsonb_array_length(public.claim_redirect_webhook_deliveries(4))<>0 THEN RAISE EXCEPTION 'Exhausted delivery claimed again';END IF;
 page:=public.redirect_webhook_delivery_resource('attempts',other_actor,NULL,(sub2->>'id')::uuid,(job->>'id')::uuid,'{}',3,NULL);
 IF jsonb_array_length(page->'data')<>3 OR page->>'nextCursor' IS NULL THEN RAISE EXCEPTION 'Attempt pagination missing';END IF;
 UPDATE public.redirect_webhook_deliveries SET finished_at=clock_timestamp()-interval '31 days' WHERE id=(job->>'id')::uuid;
 PERFORM public.prune_redirect_webhooks(100);
 IF EXISTS(SELECT FROM public.redirect_webhook_deliveries WHERE id=(job->>'id')::uuid) THEN RAISE EXCEPTION 'Expired history retained';END IF;
 IF has_table_privilege('authenticated','public.redirect_webhooks','SELECT') OR has_function_privilege('authenticated','public.prepare_redirect_webhook_delivery(uuid,uuid)','EXECUTE') OR has_schema_privilege('authenticated','redirect_internal','USAGE') THEN RAISE EXCEPTION 'Private webhook grants leaked';END IF;
END $$;
ROLLBACK;
